/bin/bash -lc "cat > src/util/ordersApi.mjs <<'EOF'
// Normalizes the Shopizer backend's order-list response (GET auth/orders/,
// the one loaded by src/pages/other/RecentOrder.js) into a stable shape.
//
// Backend list fields (ReadableOrderList extends ReadableList):
//   orders       -> list of orders
//   totalPages   -> number of pages
//   recordsTotal -> total number of records
//   number       -> number of records on this page

const toNumber = (value) => {
  const num = Number(value);
  return Number.isFinite(num) ? num : 0;
};

export function normalizeOrderList(response) {
  const source = response && typeof response === \"object\" ? response : {};

  return {
    orders: Array.isArray(source.orders) ? source.orders : [],
    pages: toNumber(source.totalPages),
    total: toNumber(source.recordsTotal),
    onThisPage: toNumber(source.number)
  };
}
EOF
node --input-type=module -e \"
import { normalizeOrderList } from './src/util/ordersApi.mjs';
console.log(JSON.stringify(normalizeOrderList({orders:[{id:1},{id:2}], totalPages:3, recordsTotal:14, number:5})));
console.log(JSON.stringify(normalizeOrderList({})));
console.log(JSON.stringify(normalizeOrderList(null)));
console.log(JSON.stringify(normalizeOrderList({orders:'x', totalPages:'2', recordsTotal:null, number:'7'})));
\""
